        "「滿月和新月時潮差最小，上、下弦月時潮差最大；資料缺值可直接視為零；若把月球放在日地之間，將預測地表出現日食影帶，而不是月面逐步變暗。」忽略、顛倒或超出題示條件；月食發生時地球位於太陽與月球之間，月球通過地球影子；不是每次望都會發生。",
